const TP_MODULES=[{"t": "The Munger latticework: a mind stocked with models", "kick": "Start here", "mins": "1.5 hrs", "obj": ["Explain Munger's latticework idea: hang experience on a framework of big models from many disciplines", "Spot the man-with-a-hammer tendency in your own reasoning and name which model you are overusing", "Describe a lollapalooza effect: several biases or forces combining to produce an extreme outcome"], "vids": [{"id": "pqzcCfUglws", "t": "The Psychology of Human Misjudgement - Charlie Munger Full Speech", "by": "BuffettMungerWisdom"}, {"id": "FlWL1Qz23co", "t": "Charlie Munger's Full 1995 Speech at Harvard", "by": "State of MedTech"}], "reads": [{"t": "Psychology of Human Misjudgment (transcript)", "u": "https:\/\/fs.blog/great-talks/psychology-human-misjudgment/", "n": "Munger's 25 standard causes of human misjudgment, in his own words."}, {"t": "Mental Models: The Best Way to Make Intelligent Decisions", "u": "https:\/\/fs.blog/mental-models/", "n": "The Farnam Street master list of the big models."}], "ex": "Pick one decision you made this month. List every mental model you actually used (not the ones you wish you had used), then name one model from another discipline that would have changed the decision.", "quiz": [{"q": "What is Munger's central claim about worldly wisdom?", "o": ["Master one discipline to expert depth before touching any other", "Build a latticework of models from many disciplines and hang experience on it", "Memorise the key facts of each field you work in", "Follow the advice of recognised experts in each field"], "a": 1}, {"q": "The man-with-a-hammer tendency describes:", "o": ["A bias towards physical over mental work", "Treating every problem as a nail because the only tool you own is a hammer", "Preferring simple tools over complex ones", "Trusting tradespeople over consultants"], "a": 1}, {"q": "Why does Munger insist on multiple models rather than one great model?", "o": ["One model forces reality to distort until it fits the model", "Multiple models look more impressive in meetings", "It makes memorisation easier", "One model is always mathematically wrong"], "a": 0}, {"q": "A lollapalooza effect happens when:", "o": ["A single bias produces a small error", "Several tendencies combine in one direction and produce an extreme outcome", "A market reaches equilibrium", "An expert changes their mind publicly"], "a": 1}, {"q": "Where does Munger say the most useful models come from?", "o": ["Business school case studies", "The big ideas of the big disciplines: psychology, mathematics, biology, economics, physics", "Management bestsellers", "Consulting frameworks"], "a": 1}, {"q": "Incentive-caused bias means:", "o": ["People respond rationally to all incentives", "People rationalise conclusions that pay them, while believing they are objective", "Incentives never affect judgement", "Only salespeople have biases"], "a": 1}, {"q": "What is the correct way to use a mental model?", "o": ["As a rigid rule that always applies", "As a lens to check against reality and combine with other models", "As a substitute for data", "As a way to win arguments"], "a": 1}, {"q": "The social-proof tendency says people:", "o": ["Always think independently under pressure", "Follow the crowd, especially under stress and uncertainty", "Only copy people they know personally", "Ignore what peers do"], "a": 1}, {"q": "Why read across disciplines instead of going deeper in your own?", "o": ["Breadth looks good on a CV", "Real problems do not respect academic boundaries", "Deep knowledge is useless", "Other fields are easier"], "a": 1}, {"q": "Munger's daily standard for learning is to:", "o": ["Read one book a week", "Go to bed a little wiser than you woke up", "Attend lectures regularly", "Debate someone smarter every day"], "a": 1}]}, {"t": "First principles: reason from the ground up", "kick": "Toolkit", "mins": "15 mins", "obj": ["Distinguish reasoning by first principles from reasoning by analogy", "Break a cost or constraint down to its physical or logical fundamentals, Musk-style", "Decide when analogy is good enough and when first principles are worth the effort"], "vids": [{"id": "NV3sBlRgzTI", "t": "The First Principles Method Explained by Elon Musk", "by": "Innomind"}], "reads": [{"t": "What is First Principles Thinking?", "u": "https:\/\/fs.blog/first-principles/", "n": "Farnam Street's canonical explainer with the Socratic method."}], "ex": "Take one 'industry rule' in a field you know (pricing, hiring, curriculum, anything). Write down the physical or logical facts underneath it, then check which parts of the rule survive.", "quiz": [{"q": "First principles thinking means:", "o": ["Copying best practice from market leaders", "Boiling a problem down to fundamental truths and reasoning up from there", "Following your first instinct", "Starting with the customer survey"], "a": 1}, {"q": "The default alternative to first principles is:", "o": ["Trial and error", "Reasoning by analogy: copying what exists with small tweaks", "Random experimentation", "Committee voting"], "a": 1}, {"q": "In Musk's rocket example, the raw materials cost about what fraction of the typical rocket price?", "o": ["About half", "Around 2 percent", "About 80 percent", "Exactly one third"], "a": 1}, {"q": "The point of the rocket example is that the prevailing price was:", "o": ["Set by physics", "Set by convention, not by physical necessity", "Impossible to change", "Determined by regulators"], "a": 1}, {"q": "Socratic questioning helps you reach first principles by:", "o": ["Asking why until you hit bedrock assumptions", "Polling wise friends", "Reading ancient philosophy", "Voting on options"], "a": 0}, {"q": "When is reasoning by analogy a sensible choice?", "o": ["Never", "For ordinary decisions where being wrong is cheap and speed matters", "Only in physics", "Whenever the CEO prefers it"], "a": 1}, {"q": "The hidden danger of reasoning by analogy is that it:", "o": ["Is slower than first principles", "Imports assumptions from a context that may not match yours", "Always produces wrong answers", "Requires too much maths"], "a": 1}, {"q": "Which question best hunts for a first principle?", "o": ["What do our competitors do?", "What must be true here regardless of anyone's opinion?", "What did we do last year?", "What is the industry standard?"], "a": 1}, {"q": "Musk applied the same method to batteries by:", "o": ["Negotiating harder with suppliers", "Breaking the cost down to raw materials on the commodities exchange", "Copying laptop battery designs", "Waiting for prices to fall"], "a": 1}, {"q": "The typical output of first principles reasoning is:", "o": ["A safer version of the status quo", "A new possibility space, often far cheaper or better than convention", "A consensus everyone likes", "A longer planning cycle"], "a": 1}]}, {"t": "Second-order thinking: and then what?", "kick": "Deceptively hard", "mins": "25 mins", "obj": ["Define second-order thinking and apply the 'and then what?' test to a live decision", "Show how a sensible first-order move (price cut, shortcut) can destroy value at the second order", "Weigh effects across time horizons, not just the immediate one"], "vids": [{"id": "WBz7VB4vA1k", "t": "Decision Making Framework | Shane Parrish", "by": "Farnam Street"}, {"id": "gOETwvNUwf0", "t": "Second Order Thinking", "by": "Moonshots Podcast"}], "reads": [{"t": "Second-Order Thinking: What Smart People Use to Outperform", "u": "https:\/\/fs.blog/second-order-thinking/", "n": "Parrish on consequences of consequences."}], "ex": "Take a decision your team or college is making this month. Write the first-order effect everyone is selling, then write two plausible second-order effects and one third-order effect. Decide if the move still looks good.", "quiz": [{"q": "Second-order thinking means:", "o": ["Thinking twice before speaking", "Asking 'and then what?' about the consequences of the consequences", "Getting a second opinion", "Ordering your priorities"], "a": 1}, {"q": "A price cut that boosts this quarter's sales is a first-order win. The likely second-order effect is:", "o": ["Nothing changes afterwards", "Competitors match, margins compress industry-wide, and share ends up similar with less profit", "Customers become permanently loyal", "Costs automatically fall"], "a": 1}, {"q": "Why is first-order thinking so common?", "o": ["It is usually right", "It is fast, easy, feels decisive, and stops at immediate visible effects", "It requires no information", "Boards demand it"], "a": 1}, {"q": "The parade example: when one person stands they see better. When everyone stands:", "o": ["Everyone still sees better", "Nobody sees better and everyone is less comfortable", "The parade moves faster", "The front row benefits"], "a": 1}, {"q": "Howard Marks' distinction between first-level and second-level thinking is that second-level thinking is:", "o": ["Simpler and faster", "Deep, convoluted and willing to see a different result from the crowd", "About doubling your estimates", "Only for investors"], "a": 1}, {"q": "Antibiotic overuse is a classic case where:", "o": ["Second-order effects do not exist", "The individual first-order gain creates a collective second-order loss (resistance)", "Doctors ignore first-order effects", "Patients think too far ahead"], "a": 1}, {"q": "Second-order thinking weighs effects across:", "o": ["Only this quarter", "Time: now, later, and much later", "Only financial metrics", "Only competitors"], "a": 1}, {"q": "A manager fires their worst performer and morale jumps. A plausible second-order effect is:", "o": ["None, morale stays high", "Fear spreads and risk-taking drops", "Salaries fall", "Hiring gets easier"], "a": 1}, {"q": "The core habit of second-order thinking is to:", "o": ["Avoid all risk", "Ask what happens next, and what happens after that, before deciding", "Wait for perfect information", "Delegate irreversible decisions"], "a": 1}, {"q": "Why do incentives make second-order thinking hard?", "o": ["Incentives have no relation to thinking", "People respond to incentives, which changes the system itself", "Incentives only affect junior staff", "Incentives simplify everything"], "a": 1}]}, {"t": "Inversion: avoid stupidity before seeking brilliance", "kick": "The judo move", "mins": "10 mins", "obj": ["Explain Jacobi's 'invert, always invert' and Munger's use of it", "Run a premortem: imagine failure first, then list its causes", "Build a stop-doing list for a real goal"], "vids": [{"id": "L0Kp7lBVM30", "t": "Charlie Munger: Invert, Always Invert", "by": "Stock Compounder"}], "reads": [{"t": "Inversion and The Power of Avoiding Stupidity", "u": "https:\/\/fs.blog/inversion/", "n": "Farnam Street on solving problems backwards."}], "ex": "Pick one goal for this semester. Write down the five behaviours that would guarantee you fail at it. Turn them into a short not-to-do list and keep it somewhere visible.", "quiz": [{"q": "Inversion as a problem-solving method means:", "o": ["Doing the opposite of what competitors do", "Solving problems backwards: instead of pursuing success, avoid what guarantees failure", "Reversing your org chart", "Copying failures"], "a": 1}, {"q": "The mathematician Jacobi's instruction was:", "o": ["Simplify, always simplify", "Invert, always invert", "Measure, always measure", "Iterate, always iterate"], "a": 1}, {"q": "Munger's famous version of inversion is:", "o": ["All I want to know is where I am going to die, so I will never go there", "Always be closing", "Never sell your winners", "Think big or go home"], "a": 0}, {"q": "Instead of asking 'how do I make this project succeed?', inversion asks:", "o": ["Who should lead it?", "What would guarantee this project fails?", "What does the data say?", "How much will it cost?"], "a": 1}, {"q": "Why does avoiding stupidity beat seeking brilliance as a strategy?", "o": ["Brilliance is illegal", "Stupidity is easier to identify and avoid than brilliance is to manufacture", "Brilliant people do not need strategy", "Stupidity is rare"], "a": 1}, {"q": "A premortem is:", "o": ["A post-project review", "Imagining the project has already failed and listing the causes in advance", "A medical procedure", "A budgeting method"], "a": 1}, {"q": "Buffett's rule one (never lose money) is inversion applied to investing because it:", "o": ["Maximises returns", "Focuses on avoiding the downside before chasing the upside", "Avoids all stocks", "Requires diversification"], "a": 1}, {"q": "Inversion and positive planning are:", "o": ["Enemies", "Complements: inversion catches the blind spots that optimism misses", "The same thing", "Only for pessimists"], "a": 1}, {"q": "Applied to a career, 'what makes people unpromotable here?' is useful because it:", "o": ["Breeds cynicism", "Reveals the failure modes to avoid, which are usually clearer than success recipes", "Is easier than working", "Annoys managers"], "a": 1}, {"q": "A good output of an inversion exercise is:", "o": ["A longer to-do list", "A stop-doing list", "A vision statement", "A bigger budget"], "a": 1}]}, {"t": "Systems thinking: stocks, flows and feedback", "kick": "See the machine", "mins": "20 mins", "obj": ["Model a situation as stocks, inflows and outflows", "Tell reinforcing feedback loops from balancing ones and give a business example of each", "Explain why delays in systems cause overshoot and oscillation"], "vids": [{"id": "RUhy9q08LbY", "t": "Operational Systems Thinking | Stocks, Flows & Feedback Loops", "by": "Learn With Dr. Hakeem-Ur-Rehman"}], "reads": [{"t": "Systems Thinking: What, Why, When, Where, and How?", "u": "https:\/\/thesystemsthinker.com/systems-thinking-what-why-when-where-and-how/", "n": "The Systems Thinker primer."}], "ex": "Draw one loop from your own life (study hours, sleep, money, fitness). Mark the stock, the inflow, the outflow, and one feedback loop. Then name one place where a small push would move the whole loop.", "quiz": [{"q": "A system, in systems thinking, is:", "o": ["A computer network", "A set of interconnected parts that produces behaviour over time", "An org chart", "A checklist"], "a": 1}, {"q": "A stock is:", "o": ["A share certificate", "An accumulation: water in a tub, cash in the bank, trust in a team", "A prediction", "A process step"], "a": 1}, {"q": "A flow is:", "o": ["A state of deep focus", "A rate that changes a stock: inflow or outflow", "A hierarchy level", "A type of meeting"], "a": 1}, {"q": "A reinforcing feedback loop is one where:", "o": ["The system self-corrects to a goal", "More produces more: compounding, network effects, panics", "Nothing changes", "Managers get feedback"], "a": 1}, {"q": "A balancing feedback loop is one that:", "o": ["Always grows", "Pushes the system towards a goal, like a thermostat", "Creates bubbles", "Balances the budget"], "a": 1}, {"q": "Why do systems surprise even smart people?", "o": ["Systems are random", "Delays between action and effect cause overshoot and oscillation", "People refuse to learn", "Data is always missing"], "a": 1}, {"q": "A leverage point, in Donella Meadows' sense, is:", "o": ["The loudest stakeholder", "A place where a small change can produce a large shift in system behaviour", "A loan", "The top of the hierarchy"], "a": 1}, {"q": "The classic systems trap in management is:", "o": ["Using too much data", "Blaming individuals for behaviour the system's structure produces", "Paying too little", "Meeting too rarely"], "a": 1}, {"q": "Hiring more people to clear a project backlog can backfire because:", "o": ["People are expensive", "Coordination cost rises and new members slow veterans before they help", "Backlogs clear themselves", "HR disapproves"], "a": 1}, {"q": "The practical systems habit before intervening is to:", "o": ["Pull the biggest lever first", "Draw the loop before you pull the lever", "Form a committee", "Copy a competitor"], "a": 1}]}, {"t": "Probabilistic thinking: bet on the odds, not the outcome", "kick": "Bet well", "mins": "45 mins", "obj": ["Judge decisions by process and odds rather than by outcome (avoid 'resulting')", "Use base rates as the starting point for any forecast", "Compute rough expected value and update estimates with new evidence"], "vids": [{"id": "uYNsSeYjkp4", "t": "Thinking in Bets | Annie Duke | Talks at Google", "by": "Talks at Google"}], "reads": [{"t": "The Value of Probabilistic Thinking", "u": "https:\/\/fs.blog/probabilistic-thinking/", "n": "Farnam Street on fat tails, base rates and Bayes."}], "ex": "Write three predictions about the next month (marks, placements, a launch, anything) with rough percentage chances. Date them. Check back in a month and score yourself.", "quiz": [{"q": "Probabilistic thinking means:", "o": ["Being certain about everything", "Estimating likelihoods and updating them instead of thinking in binary terms", "Avoiding all risks", "Using statistics software"], "a": 1}, {"q": "Annie Duke's 'resulting' is the error of:", "o": ["Judging a decision's quality by its outcome rather than by the process and odds at the time", "Reviewing results too often", "Making decisions in groups", "Trusting experts"], "a": 0}, {"q": "A base rate is:", "o": ["The interest rate banks charge", "The prior frequency of an event in the relevant reference class", "The average of your guesses", "A tax concept"], "a": 1}, {"q": "Base-rate neglect looks like:", "o": ["Assuming your startup will succeed because you believe in it, while ignoring that most fail", "Checking industry statistics", "Comparing against peers", "Using historical data"], "a": 0}, {"q": "Expected value is:", "o": ["The most likely outcome", "The probability-weighted average of all outcomes", "The best-case outcome", "The worst-case outcome"], "a": 1}, {"q": "A positive expected-value bet can still lose. The right response after it loses is to:", "o": ["Abandon the approach", "Judge the bet, not the roll: check whether the odds were really in your favour", "Double the stakes immediately", "Blame randomness"], "a": 1}, {"q": "Bayesian updating means:", "o": ["Reversing your beliefs daily", "New evidence shifts your estimate, but rarely all the way to zero or one hundred percent", "Ignoring priors", "Averaging all opinions"], "a": 1}, {"q": "Fat tails warn us that:", "o": ["Distributions are always normal", "Rare, extreme events happen more often than standard models assume and can dominate outcomes", "Averages are useless", "Risk can be eliminated"], "a": 1}, {"q": "Why put rough percentages on forecasts instead of words like 'likely'?", "o": ["Percentages look scientific", "Words hide disagreement; numbers let you compare, update and check calibration", "Numbers are always right", "Words are unprofessional"], "a": 1}, {"q": "The long-run payoff of probabilistic thinking is:", "o": ["You never lose", "Better average decisions, because process quality compounds even when single outcomes are luck", "Certainty", "Faster decisions"], "a": 1}]}, {"t": "Circle of competence: know its edge", "kick": "Stay in bounds", "mins": "15 mins", "obj": ["Define a circle of competence and explain why the edge matters more than the size", "Audit where your own predictions have actually been right", "Choose what to do when a decision falls outside your circle"], "vids": [{"id": "eIUFGSbaxg8", "t": "Warren Buffett: Here's How To Determine Your Circle of Competence", "by": "Adam J. Mead"}], "reads": [{"t": "Mastering Success: Navigating Within Your Circle of Competence", "u": "https:\/\/fs.blog/circle-of-competence/", "n": "Farnam Street on finding and widening the edge."}], "ex": "Draw your circle honestly: three areas where your judgement has a proven track record, and three where you are guessing. For one area outside, write the cheapest way to either learn it or find someone whose circle covers it.", "quiz": [{"q": "A circle of competence is:", "o": ["Your job description", "The area you genuinely understand; knowing its edge matters more than its size", "Your social network", "A certification"], "a": 1}, {"q": "Buffett's key point about the circle is that:", "o": ["Bigger is always better", "What matters is knowing the perimeter, not how large it is", "It cannot be widened", "Only investors have one"], "a": 1}, {"q": "Why do investors usually lose money outside their circle?", "o": ["Bad luck", "They buy businesses they cannot actually evaluate", "Markets are rigged", "They diversify too much"], "a": 1}, {"q": "The honest way to find your circle's edge is to:", "o": ["Ask your friends", "Look at your track record: where your predictions proved right", "Read more books", "Take a personality test"], "a": 1}, {"q": "Your circle of competence:", "o": ["Is fixed at birth", "Can be deliberately widened with study and experience", "Shrinks every year", "Is whatever your degree says"], "a": 1}, {"q": "A good test of whether something is inside your circle:", "o": ["You enjoy it", "You can explain in plain words how it makes money and how it fails", "You have watched a documentary about it", "Your friends do it"], "a": 1}, {"q": "The main obstacle to knowing your circle is:", "o": ["Lack of information", "Ego: we systematically overestimate what we understand", "Lack of time", "Teachers"], "a": 1}, {"q": "Munger's 'too hard' pile is:", "o": ["A list of enemies", "Where he puts problems outside the circle instead of forcing an answer", "His reading backlog", "Failed investments"], "a": 1}, {"q": "Applied to careers, the circle suggests you should:", "o": ["Do what is popular", "Play games where your skills are scarce rather than where you are average", "Avoid all competition", "Switch fields often"], "a": 1}, {"q": "When a decision sits outside your circle, the right move is to:", "o": ["Guess confidently", "Pass, or bring in someone whose circle covers it", "Delay forever", "Outsource all judgement to data"], "a": 1}]}, {"t": "The map is not the territory: models are tools, not truth", "kick": "The capstone", "mins": "20 mins", "obj": ["Explain the map-territory distinction and why every framework in this track is a map", "Apply Goodhart's law: when a measure becomes a target it stops measuring", "Decide what to trust when the model and the reality disagree"], "vids": [{"id": "EUE__gO-2hE", "t": "The Map is Not the Territory", "by": "Vishal Khandelwal"}, {"id": "cuEJb__ZUnY", "t": "The Map is not the Territory (Mental Model Monday)", "by": "Zach Cresswell"}], "reads": [{"t": "The Map and the Territory", "u": "https:\/\/fs.blog/map-and-territory/", "n": "Farnam Street on why abstractions leak."}], "ex": "Pick one number you or your institution obsess over (CGPA, revenue target, follower count). Write what the number is a map of, what it leaves out, and one way gaming the number would hurt the real thing.", "quiz": [{"q": "'The map is not the territory' means:", "o": ["Maps are always wrong", "Models, metrics and descriptions are not reality itself", "Geography is subjective", "Only old maps mislead"], "a": 1}, {"q": "Why does the distinction matter for decisions?", "o": ["It does not; maps are enough", "We act on maps (KPIs, frameworks, forecasts) and forget the gap between them and reality", "Territory changes too fast", "Maps are expensive"], "a": 1}, {"q": "Goodhart's law states that:", "o": ["Measurement improves performance", "When a measure becomes a target, it ceases to be a good measure", "Goals should be ambitious", "Data beats intuition"], "a": 1}, {"q": "A financial model of a market is:", "o": ["The market itself", "A map: useful compression of reality, with omissions", "Always wrong", "A guarantee"], "a": 1}, {"q": "If maps are not the territory, why use them at all?", "o": ["We should not", "They compress complexity so we can act; the trick is remembering the gap", "They are legally required", "They impress stakeholders"], "a": 1}, {"q": "The classic failure mode Goodhart describes is:", "o": ["Underinvestment", "Optimising the metric while the real thing quietly rots", "Too much experimentation", "Slow decision-making"], "a": 1}, {"q": "When reality and the model disagree, the right move is to:", "o": ["Trust the model", "Trust the territory and revise the map", "Average the two", "Stop collecting data"], "a": 1}, {"q": "Customer interviews sit where in this framing?", "o": ["They are the map", "Closer to the territory than any dashboard", "Neither map nor territory", "They are noise"], "a": 1}, {"q": "How does this model relate to the other seven in this track?", "o": ["It replaces them", "Every mental model is itself a map: useful, incomplete, never the ground truth", "It contradicts them", "It only applies to geography"], "a": 1}, {"q": "The habit this module wants installed is:", "o": ["Distrust all frameworks", "Hold models loosely: use them hard, update them fast, never worship them", "Avoid metrics entirely", "Build more detailed maps"], "a": 1}]}];

const EC_MODULES=[{"t": "The Pyramid Principle: answer first, then prove it", "kick": "Start here", "mins": "30 mins", "obj": ["Explain Minto's core rule: state the governing thought first, then support it with grouped arguments", "Apply the vertical rule (each level answers the 'why' or 'how' of the level above) and the horizontal rule (each level is MECE and parallel)", "Rewrite a bottom-up, mystery-novel email into answer-first form"], "vids": [{"id": "elMPIxLYtoc", "t": "Consultant Explains the Pyramid Principle", "by": "Analyst Academy"}, {"id": "j4Y3TdVVBCA", "t": "The Minto Pyramid Principle Explained with Examples", "by": "EPM"}], "reads": [{"t": "The Pyramid Principle: Book Summary and Review (StrategyU)", "u": "https:\/\/strategyu.co/pyramid-principle-partone/", "n": "A consultant's walkthrough of logic in writing."}, {"t": "Book Summary: The Pyramid Principle (To Summarise)", "u": "https:\/\/www.tosummarise.com/book-summary-the-pyramid-principle-by-barbara-minto/", "n": "Compact summary of Minto's book."}], "ex": "Take the last long message or email you sent. Write its single governing thought in one sentence. Then list the two to four arguments that support it, each in one sentence. Check: does each argument answer a 'why' or 'how' from the sentence above it?", "quiz": [{"q": "The Pyramid Principle's core rule is:", "o": ["Build suspense before the conclusion", "State the answer or recommendation first, then group the supporting arguments beneath it", "Always present data before opinions", "Write chronologically"], "a": 1}, {"q": "Why answer-first for executive audiences?", "o": ["It sounds confident", "They decide under time pressure; the conclusion up front lets them follow or challenge your logic immediately", "It is shorter", "It hides weak analysis"], "a": 1}, {"q": "The vertical rule of the pyramid says every level must:", "o": ["Introduce a new topic", "Answer the 'why?' or 'how?' raised by the point above it", "Contain a chart", "Be longer than the level above"], "a": 1}, {"q": "The horizontal rule says points at the same level must be:", "o": ["Unrelated and surprising", "Mutually exclusive, collectively exhaustive, and the same kind of idea", "Chronological", "Equal in length"], "a": 1}, {"q": "Minto's ways to order ideas within a group include:", "o": ["Alphabetical order", "Time, structure, or degree of importance", "Random order", "By length"], "a": 1}, {"q": "The classic anti-pattern Minto warns against is:", "o": ["Starting with the answer", "Walking the reader through your analysis chronologically and revealing the conclusion at the end", "Using headings", "Numbering your points"], "a": 1}, {"q": "In Minto's introduction structure, the situation-complication pair exists to:", "o": ["Pad the opening", "Raise the specific question your answer resolves", "Show off research", "Set a deadline"], "a": 1}, {"q": "The governing thought is:", "o": ["The longest sentence in the document", "The single sentence the whole document exists to prove", "The first quote from a stakeholder", "The appendix title"], "a": 1}, {"q": "Applied to a short update email, the pyramid means:", "o": ["Attachments first", "The ask or decision lands in the first one or two lines", "A formal greeting matters most", "Bullet points are banned"], "a": 1}, {"q": "A practical test of a well-built pyramid:", "o": ["It uses exactly three points", "A reader who reads only the top box and the first line of each group still gets the argument", "Every paragraph has a citation", "It fills exactly one page"], "a": 1}]}, {"t": "MECE: split the problem without gaps or overlaps", "kick": "The consultant's sieve", "mins": "20 mins", "obj": ["Define mutually exclusive and collectively exhaustive, and say why each half matters", "Use the five classic MECE splits (formula, process, segments, opposites, frameworks) on a real problem", "Build a small issue tree whose branches are clean at every level"], "vids": [{"id": "6kReKGrcoSc", "t": "How To Be MECE", "by": "Management Consulted"}, {"id": "Vl7b_vpuLxE", "t": "The MECE Principle", "by": "PrepLounge"}], "reads": [{"t": "The 5 Ways to be MECE in Case Interviews (Crafting Cases)", "u": "https:\/\/www.craftingcases.com/the-5-ways-to-be-mece/", "n": "Formula, process, segments, opposites and frameworks, with examples."}, {"t": "MECE Framework: Case Interview Example (Management Consulted)", "u": "https:\/\/managementconsulted.com/mece-framework-case-interview-example/", "n": "A worked case split."}], "ex": "Take a problem from your own work or studies (falling attendance, rising costs, low placement conversion). Split it two levels deep using two different MECE lenses (for example: formula split, then process split). Check every level for overlaps and gaps.", "quiz": [{"q": "MECE stands for:", "o": ["Most efficient, cost effective", "Mutually exclusive, collectively exhaustive", "Measure everything, challenge everyone", "Manage each case equally"], "a": 1}, {"q": "'Mutually exclusive' means:", "o": ["Ideas cannot coexist", "Each item belongs to exactly one bucket, no overlaps", "Buckets must be equal size", "Items are ranked by value"], "a": 1}, {"q": "'Collectively exhaustive' means:", "o": ["The list is exhausting to read", "The buckets together cover the entire problem, no gaps", "Every customer is surveyed", "The analysis is complete in one day"], "a": 1}, {"q": "Which of these is a MECE split of company profit?", "o": ["Revenue, costs, marketing", "Revenue and costs", "Sales, marketing, operations", "Fixed costs and salaries"], "a": 1}, {"q": "The danger of overlapping buckets is:", "o": ["Nothing, overlap is safe", "Double-counted causes and confused ownership of the fix", "Too much data", "Slower presentations"], "a": 1}, {"q": "The danger of a gap in your split is:", "o": ["The real driver hides in 'other' and the answer is wrong", "The report looks short", "Stakeholders feel excluded", "Charts become uneven"], "a": 0}, {"q": "The five classic MECE lenses are:", "o": ["SWOT, PESTEL, Porter, BCG, Ansoff", "Formula or math, process steps, customer or product segments, opposites, and conceptual frameworks", "Past, present, future", "People, process, technology"], "a": 1}, {"q": "An issue tree stays MECE when:", "o": ["It has three branches per level", "Branches at each level together answer the level above, without overlapping each other", "Every branch has data", "It fits on one slide"], "a": 1}, {"q": "When a perfectly MECE split is impossible, the professional move is to:", "o": ["Force one anyway", "Use a sensible, disclosed approximation rather than false precision", "Skip structuring", "Average two splits"], "a": 1}, {"q": "In communication, MECE shows up as:", "o": ["Longer documents", "Sections and slides that each carry one distinct message, together covering the argument", "More appendices", "Fewer headings"], "a": 1}]}, {"t": "SCQA: storylining that lands", "kick": "Narrative", "mins": "20 mins", "obj": ["Name the four SCQA parts and the job each one does", "Write a situation that is uncontroversial and a complication that creates real tension", "Choose when to lead with the answer instead (answer-first variant)"], "vids": [{"id": "0JVV1H_uD_M", "t": "SCQA: Situation, Complication, Question, Answer - A Consulting Problem Solving Framework", "by": "StrategyU"}, {"id": "HnlWiVs9P5o", "t": "PowerPoint Storytelling: How McKinsey, Bain and BCG create compelling presentations", "by": "Analyst Academy"}], "reads": [{"t": "SCQA - Overview and Practical Examples (Corporate Finance Institute)", "u": "https:\/\/corporatefinanceinstitute.com/resources/career/scqa/", "n": "SCQA with worked business examples."}, {"t": "SCQA: What is it and how does it work? (Analytic Storytelling)", "u": "https:\/\/analytic-storytelling.com/scqa-what-is-it-how-does-it-work-and-how-can-it-help-me/", "n": "Practical SCQA writing guide."}], "ex": "Write an SCQA for a real ask you need to make this week (to a professor, manager or client). Four sentences, one per letter. Then write the answer-first variant and decide which audience gets which version.", "quiz": [{"q": "SCQA stands for:", "o": ["Strategy, Cost, Quality, Action", "Situation, Complication, Question, Answer", "Summary, Context, Quote, Ask", "Scope, Cause, Query, Act"], "a": 1}, {"q": "The situation's job is to:", "o": ["Impress the audience with data", "State context the audience already accepts, so everyone starts on common ground", "Introduce the hero", "List every stakeholder"], "a": 1}, {"q": "The complication's job is to:", "o": ["Complicate the analysis", "Introduce the tension or change that makes the status quo untenable", "Present the solution", "Add emotional drama"], "a": 1}, {"q": "The question in SCQA should:", "o": ["Be rhetorical and clever", "Arise naturally from the situation plus complication: essentially 'so what should we do?'", "Come before the complication", "Be avoided"], "a": 1}, {"q": "The answer is:", "o": ["A cliffhanger", "Your governing thought: the recommendation the rest of the document supports", "A menu of options", "The appendix"], "a": 1}, {"q": "Why does story structure persuade better than a fact list?", "o": ["Stories are shorter", "The complication creates tension the audience wants resolved, so they lean in for the answer", "Facts are unpersuasive", "Stories require no evidence"], "a": 1}, {"q": "For an impatient senior audience, the right variant is to:", "o": ["Drop the answer", "Lead with the answer, then supply situation and complication as context", "Extend the situation", "Skip the question"], "a": 1}, {"q": "The most common SCQA mistake is:", "o": ["Too little data", "A situation so long that the audience checks out before the complication arrives", "Too few slides", "Starting with the answer"], "a": 1}, {"q": "On a single slide, SCQA becomes:", "o": ["Four slides minimum", "The action title states the answer and the body carries the support", "A four-box diagram", "A video"], "a": 1}, {"q": "An action title is:", "o": ["A verb in the title", "A full-sentence slide title that states the takeaway, not the topic", "A call to action for the reader", "A slide with animation"], "a": 1}]}, {"t": "Write like an executive: memos that get read", "kick": "Capstone", "mins": "25 mins", "obj": ["Explain why Amazon banned PowerPoint and what narratively structured memos force writers to do", "Apply BLUF: bottom line up front, with the ask and deadline in the first lines", "Edit a draft: one idea per paragraph, precise numbers over adjectives, then cut a third"], "vids": [{"id": "e47wAgIhZ7o", "t": "Jeff Bezos on banning PowerPoint in meetings at Amazon", "by": "Lex Clips"}, {"id": "NE8DX8_Xg4E", "t": "Jeff Bezos on Writing Memos at Amazon", "by": "PodiumVC"}], "reads": [{"t": "How to write an Amazon-style narrative memo (SEO MBA)", "u": "https:\/\/newsletter.seomba.com/p/how-to-write-an-amazon-style-narrative", "n": "Structure and habits of a six-page narrative."}, {"t": "Why Jeff Bezos makes Amazon execs read 6-page memos (CNBC)", "u": "https:\/\/www.cnbc.com/2018/04/23/what-jeff-bezos-learned-from-requiring-6-page-memos-at-amazon.html", "n": "The reasoning behind the memo rule."}], "ex": "Rewrite one page of something you wrote recently as an executive memo: decision or ask in the first two lines, one idea per paragraph, every vague adjective replaced by a number or a fact. Cut it by a third without losing meaning.", "quiz": [{"q": "Amazon's famous meeting rule is:", "o": ["Slides limited to ten", "No PowerPoint in senior meetings; narratively structured six-page memos, read silently at the start", "Meetings capped at 15 minutes", "No meetings before noon"], "a": 1}, {"q": "Why did Bezos prefer memos over slides?", "o": ["Memos are cheaper", "Narrative forces complete thought; bullet slides can hide weak logic and gaps in reasoning", "Slides load slowly", "Memos are shorter"], "a": 1}, {"q": "The test of a great memo, in Bezos's framing, is that:", "o": ["It has an executive summary", "The reasoning stands on its own without the writer in the room to explain it", "It fits on one page", "It uses no numbers"], "a": 1}, {"q": "BLUF means:", "o": ["Best lines used first", "Bottom line up front: the conclusion or ask in the opening lines", "Bold, large, underlined font", "Briefing leaders under fire"], "a": 1}, {"q": "An executive email should open with:", "o": ["A warm greeting", "The ask or decision, plus the deadline if there is one", "Background context", "A thank-you"], "a": 1}, {"q": "The paragraph discipline of executive writing is:", "o": ["One idea per paragraph, with topic sentences carrying the argument", "Long paragraphs show depth", "One sentence per paragraph always", "Paragraphs are optional"], "a": 0}, {"q": "In a memo, precise numbers with sources beat adjectives because:", "o": ["Numbers look impressive", "They let the reader check your reasoning instead of trusting your enthusiasm", "Adjectives are unprofessional", "Numbers are shorter"], "a": 1}, {"q": "Bezos's editing advice for great memos includes:", "o": ["Write once and send", "Write, set aside, rewrite, and get colleagues to mark it up", "Dictate instead of typing", "Hire speechwriters"], "a": 1}, {"q": "Silent reading at the start of the meeting guarantees:", "o": ["A quiet office", "Everyone has actually read the memo, so discussion starts informed", "Time is saved", "Decisions are unanimous"], "a": 1}, {"q": "The 'cut a third' rule exists because:", "o": ["Attention is scarce; tighter writing forces clearer thinking", "Documents have page limits", "Editors need work", "Short emails get faster replies"], "a": 0}]}];

